// VaryBenchMixed applies the §2.2 LCG mapping: value fields only, structure held
// fixed so bytes/op never moves.
func VaryBenchMixed(v *BenchMixed, rng uint64) {
	v.Sequence = uint32((rng >> 3) & 0xffff)
	v.AckSequence = int32((rng >> 16) & 0xffff)
	v.AckBits = uint32((rng >> 29) & 0xffffffff)
	v.SessionId = uint64(rng)
	v.ClientId = uint32((rng >> 22) & 0xffffffff)
	v.Nonce = uint64(rng)
	v.WorldTime = int64((rng>>6)&0xffffffffff) - 1000000000000
	v.FrameTick = uint64((rng >> 9) & 0xffffffffffff)
	v.ServerTime = int32((rng >> 23) & 0x7fffff)
	for i0 := 0; i0 < 8; i0++ {
		e0 := &v.Entities[i0]
		e0.EntityId = uint32((rng >> ((24 + i0) & 31)) & 0xfff)
		e0.PosY = int32((rng>>((5+i0)&31))&0x3fff) - 16383
		e0.Yaw = uint32((rng >> ((18 + i0) & 31)) & 0x1ff)
		e0.VelX = int32((rng>>((31+i0)&31))&0xfff) - 2048
		e0.VelZ = int32((rng>>((12+i0)&31))&0xfff) - 2048
		e0.Weapon = MixedWeapon((rng >> ((25 + i0) & 31)) & 0xf)
		e0.Moving = (rng>>((6+i0)&31))&0x1 != 0
	}
	for i0 := 0; i0 < 80; i0++ {
		e0 := &v.Stats[i0]
		e0.StatId = uint32((rng >> ((19 + i0) & 31)) & 0xff)
	}
	v.GameEvent.Hit.TargetId = uint32((rng >> 12) & 0xfff)
	v.GameEvent.Hit.Damage = int32((rng >> 25) & 0xfff)
	v.GameEvent.Hit.HitKind = int32((rng >> 2) & 0x7)
	v.GameEvent.Hit.Crit = (rng>>7)&0x1 != 0
	v.Loadout[0] = uint8((rng >> 48) & 0xff)
	v.PlayerName[7] = byte(65 + ((rng >> 45) & 0xf))
	v.Payload[0] = byte((rng >> 17) & 0xff)
	v.AimX = -1.0 + float32((rng>>25)&0x7f)*0.015625
	v.AimY = -1.0 + float32((rng>>38)&0x7f)*0.015625
	v.AimZ = -1.0 + float32((rng>>51)&0x7f)*0.015625
	v.Recoil = float32((rng >> 11) & 0xffff)
	v.Drift = float64((rng>>39)&0xffffff) * 0.5
	v.WideKey = serialize.Uint128{Lo: rng, Hi: rng >> 1}
	v.Flux = serialize.Int128{Lo: (rng >> 2) & 0xffffffffffff, Hi: 0}
	v.Ping = uint16((rng >> 6) & 0x7fff)
	v.CrcHint = uint32((rng >> 9) & 0xffffff)
	v.Extra = int32((rng >> 33) & 0xff)
}
